/**
 * Возвращает HTML карточек услуг для заданного таба.
 *
 * @param string $cat_slug 'all' или slug рубрики.
 * @return string HTML.
 */
function get_services_cards( $cat_slug ) {
    $args = [
        'post_type'      => 'service',
        'posts_per_page' => -1,
        'orderby'        => 'menu_order',
        'order'          => 'ASC',
    ];
    if ( 'all' !== $cat_slug ) {
        $args['tax_query'] = [
            [
                'taxonomy' => 'service_cat',
                'field'    => 'slug',
                'terms'    => $cat_slug,
            ],
        ];
    }
    $query = new WP_Query( $args );
    $cards = '';
    if ( $query->have_posts() ) {
        while ( $query->have_posts() ) {
            $query->the_post();
            $img_url = get_the_post_thumbnail_url( get_the_ID(), 'medium' ) ?: '';
            $img_alt = get_the_title();
            $link    = get_permalink();
            $cards .= '<article class="tabs__card">';
            if ( $img_url ) {
                $cards .= '<div class="tabs__pict"><img src="' . esc_url( $img_url ) . '" alt="' . esc_attr( $img_alt ) . '" class="_image"></div>';
            }
            $cards .= '<h4 class="tabs__card-title"><a href="' . esc_url( $link ) . '" target="_blank" rel="noopener noreferrer">' . esc_html( get_the_title() ) . '</a></h4>';
            $cards .= '</article>';
        }
        wp_reset_postdata();
    } else {
        $cards .= '<p>В этой категории услуг пока нет.</p>';
    }
    return $cards;
}
