<section class="tabs _section-1 _section-mt">
    <div class="container">
        <h2 class="tabs__title _title-2">Услуги и акции</h2>

        <!-- Навигация табов -->
        <div class="tabs__nav">
            <?php foreach ( $tabs as $tab ) : 
                $btn_class = 'tabs__btn _btn _btn-secondary ' . ( $tab['class'] ?? '' );
            ?>
                <button class="<?php echo esc_attr( trim( $btn_class ) ); ?>" data-tab="tab-<?php echo esc_attr( $tab['slug'] ); ?>">
                    <?php echo ! empty( $tab['icon'] ) ? $tab['icon'] : ''; ?>
                    <?php echo esc_html( $tab['title'] ); ?>
                </button>
            <?php endforeach; ?>
        </div>

        <!-- Панели табов (десктоп) -->
        <div class="tabs__content">
            <?php foreach ( $tabs as $tab ) : ?>
                <div class="tabs__pane" data-tab="tab-<?php echo esc_attr( $tab['slug'] ); ?>">
                    <?php echo get_services_cards( $tab['slug'] ); ?>
                </div>
            <?php endforeach; ?>
        </div>

        <!-- Аккордеон (мобильная версия) -->
        <div class="accordion">
            <?php foreach ( $tabs as $tab ) : 
                $acc_class = 'accordion__header _btn _btn-primary ' . ( $tab['class'] ?? '' );
            ?>
                <div class="accordion__item">
                    <button class="<?php echo esc_attr( trim( $acc_class ) ); ?>" data-accordion="tab-<?php echo esc_attr( $tab['slug'] ); ?>">
                        <?php echo esc_html( $tab['title'] ); ?>
                    </button>
                    <div class="accordion__content" data-accordion-content="tab-<?php echo esc_attr( $tab['slug'] ); ?>">
                        <div class="accordion__inner">
                            <?php echo get_services_cards( $tab['slug'] ); ?>
                        </div>
                    </div>
                </div>
            <?php endforeach; ?>
        </div><!-- .accordion -->
    </div>
</section>